Method.Source:
/// <summary>
/// Purchase order number parameter
/// </summary>
/// <param name = "_purchId">purchId</param>
/// <returns>purchId</returns>
[
    DataMemberAttribute,
    SysOperationLabelAttribute(literalStr("@SYS25204")),
    SysOperationControlVisibilityAttribute(false)

]
public PurchId parmPurchId(PurchId _purchId = purchId)
{
    purchId = _purchId;

    return purchId;
}

/// <summary>
/// Reprint parameter
/// </summary>
/// <param name = "_isReprint">Reprint</param>
/// <returns>Boolean value</returns>
[
    DataMemberAttribute,
    SysOperationLabelAttribute(literalStr("@MET:Reprint")),
    SysOperationControlVisibilityAttribute(false)

]
public boolean parmIsRePrint(boolean _isReprint = isReprint)
{
    isReprint = _isReprint;

    return isReprint;
}
